pt-BR.code:
padrao, texto = "aaab", "aaaaaaab"
pi = [0, 1, 2, 0]
q = comparacoes = 0
for c in texto:
    while True:
        comparacoes += 1
        if padrao[q] == c:
            q += 1
            break
        if q == 0:
            break
        q = pi[q - 1]
    if q == len(padrao):
        q = pi[q - 1]
print(comparacoes)

